135	/// Something that happened to a job.
136	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
137	#[serde(rename_all = "snake_case", tag = "kind")]
138	pub enum Event {
139	    /// A sandbox is free for this queued job.
140	    Admitted,
141	    Provisioned,
142	    ProvisionFailed {
143	        error: String,
144	    },
145	    TurnFinished {
146	        outcome: Outcome,
147	    },
148	    /// A person approved the step the job waits on.
149	    Approved,
150	    /// A person sent the step's result back with a note, or answered a question.
151	    Commented {
152	        text: String,
153	    },
154	    /// The job's branch merged, or was left, as its workspace says (D41).
155	    Landed,
156	    LandFailed {
157	        error: String,
158	    },
159	    Stopped,
160	    /// A shell step passed, with what it printed.
161	    Ran {
162	        output: String,
163	    },
164	    /// A shell step failed, with what it printed.
165	    StepFailed {
166	        detail: String,
167	    },
168	    /// A step found what only a person can settle; no fix is sent.
169	    StepStuck {
170	        detail: String,
171	    },
172	    /// The job's VM is gone, as after its stack restarted. Its commits are
173	    /// in the worktree, so a new VM picks the job up where it was (revive).
174	    VmLost,
175	    /// A person asked to run a failed job, or a stuck step, again.
176	    Retried,
177	    /// A person gave the running turn its full cap again, from now.
178	    Extended,
179	}
