181	/// Whether a person oversees a step (D33). Stored `ask` and `hold` read as
182	/// lights-on, and `auto` as dark.
183	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
184	#[serde(rename_all = "snake_case")]
185	pub enum Dial {
186	    /// The step waits for a person to approve its result or send it back.
187	    #[default]
188	    #[serde(alias = "ask", alias = "hold")]
189	    LightsOn,
190	    /// The step goes on at once.
191	    #[serde(alias = "auto")]
192	    Dark,
193	}
