195	/// How much of a workflow a person oversees, as its steps' dials make it:
196	/// a gate at every step, at some, or at none.
197	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
198	#[serde(rename_all = "snake_case")]
199	pub enum Level {
200	    LightsOn,
201	    Dim,
202	    Dark,
203	}
