205	/// What bounds one job's run beyond its workflow.
206	#[derive(Clone, Debug, Default, PartialEq, Eq)]
207	pub struct Bounds {
208	    /// An eval's run: every step goes on at once, and it stops before its
209	    /// finish, so nothing lands.
210	    pub trial: bool,
211	    /// How many times in all the job's steps may send its work back by
212	    /// themselves; past it, a failing step waits on the owner. It comes from
213	    /// the job's workspace.
214	    pub revision_budget: Option<u32>,
215	    /// What each step's turns have cost so far, by step id, in millionths of
216	    /// a US dollar, for the steps' own budgets (D43).
217	    pub spent: BTreeMap<String, u64>,
218	}
