220	/// How an agent turn ended.
221	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
222	#[serde(rename_all = "snake_case", tag = "kind")]
223	pub enum Outcome {
224	    /// The turn finished its step, with the text it reported.
225	    Done { report: String },
226	    /// The agent stopped with a question for the owner.
227	    Asked { question: String },
228	    /// The turn failed, or ran past the cap.
229	    Failed { error: String },
230	    /// The turn replied, but not with what its step asked for, such as a
231	    /// result it must give.
232	    Unusable { report: String, problem: String },
233	}
