235	/// What the adapter must do after a step. Effects are data; the core never
236	/// waits on one (§6.1).
237	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
238	#[serde(rename_all = "snake_case", tag = "kind")]
239	pub enum Effect {
240	    /// Make the job's worktree and VM, and put its code in the VM.
241	    Provision,
242	    StartTurn {
243	        stage: Stage,
244	        brief: String,
245	    },
246	    /// Keep a step's report or output as its artifact, under the step's id.
247	    RecordArtifact {
248	        stage: Stage,
249	        step: String,
250	        body: String,
251	    },
252	    /// Keep the change against its base as step `step`'s artifact, and review it.
253	    CaptureDiff {
254	        stage: Stage,
255	        step: String,
256	    },
257	    /// Run a shell step, then send `Ran`, `StepFailed` or `StepStuck`.
258	    RunStep {
259	        stage: Stage,
260	    },
261	    /// The workflow's last step passed: bring the VM's commits back, then
262	    /// merge them or leave the branch, as the workspace says (D41).
263	    Finish,
264	    /// Stop the VM and release the worktree.
265	    Teardown,
266	    /// A dark step went on with no person (D33): note it in the audit log.
267	    DarkDecided {
268	        stage: Stage,
269	    },
270	}
