272	impl Job {
273	    pub fn new(id: String, workspace: String, request: String, at: u64) -> Self {
274	        Job {
275	            id,
276	            workspace,
277	            request,
278	            stage: Stage::Prompt,
279	            state: State::Queued,
280	            question: None,
281	            feedback: None,
282	            failures: 0,
283	            error: None,
284	            updated_at: at,
285	            revisions: BTreeMap::new(),
286	            last_refusal: None,
287	            flow: Vec::new(),
288	            node: None,
289	            results: BTreeMap::new(),
290	            failed: Default::default(),
291	        }
292	    }
293	
294	    /// The step the job is at.
295	    pub fn step(&self) -> Option<&workflow::Step> {
296	        let at = self.node.as_deref()?;
297	        self.flow.iter().find(|s| s.id == at)
298	    }
299	
300	    /// The job on a workflow's steps, at its first step.
301	    pub fn running(mut self, flow: Vec<workflow::Step>) -> Self {
302	        if let Some(first) = flow.first() {
303	            self.stage = first.stage;
304	            self.node = Some(first.id.clone());
305	        }
306	        self.flow = flow;
307	        self
308	    }
309	
310	    /// Past its last step: the job finishes (D41).
311	    pub fn finishing(&self) -> bool {
312	        self.node.is_none() && !self.flow.is_empty()
313	    }
314	
315	    fn position(&self) -> Option<usize> {
316	        let at = self.node.as_ref()?;
317	        self.flow.iter().position(|s| &s.id == at)
318	    }
319	
320	    /// Move to step `i` of the workflow.
321	    fn go_to(&mut self, i: usize) {
322	        let step = &self.flow[i];
323	        (self.stage, self.node) = (step.stage, Some(step.id.clone()));
324	        self.failures = 0;
325	    }
326	
327	    /// The nearest agent's step at or before this one, which a failing or
328	    /// sent-back step's work goes back to.
329	    fn fixer(&self) -> Option<usize> {
330	        let at = self.position()?;
331	        (0..=at)
332	            .rev()
333	            .find(|&i| self.flow[i].stage.kind() == Kind::Turn && !self.flow[i].reach.reads_only)
334	    }
335	}
