337	/// Apply one event to one job. An event that does not fit the job's state
338	/// changes nothing and returns no effects.
339	pub fn step(job: &Job, event: &Event, at: u64, bounds: &Bounds) -> (Job, Vec<Effect>) {
340	    let mut next = job.clone();
341	    next.updated_at = at;
342	    let effects = match (job.state, event) {
343	        (_, Event::Retried | Event::Extended) => match by_person(&mut next, event) {
344	            Some(effects) => effects,
345	            None => return (job.clone(), Vec::new()),
346	        },
347	        (state, _) if state.finished() => return (job.clone(), Vec::new()),
348	        (_, Event::Stopped) => {
349	            next.state = State::Stopped;
350	            vec![Effect::Teardown]
351	        }
352	        (State::Queued, Event::Admitted) => {
353	            next.state = State::Provisioning;
354	            vec![Effect::Provision]
355	        }
356	        (State::Provisioning, Event::Provisioned) => start_within(&mut next, bounds),
357	        (State::Provisioning, Event::ProvisionFailed { error }) => fail(&mut next, error),
358	        (State::Running, Event::TurnFinished { outcome }) if job.stage.kind() == Kind::Turn => {
359	            turn_finished(&mut next, outcome, bounds)
360	        }
361	        (State::NeedsYou, Event::Approved) if job.question.is_none() => approved(&mut next, bounds),
362	        (State::NeedsYou, Event::Commented { text }) => commented(&mut next, text),
363	        (State::Running, Event::VmLost) => revive(&mut next),
364	        (State::Running, Event::Landed | Event::LandFailed { .. }) if job.finishing() => {
365	            finished(&mut next, event)
366	        }
367	        (
368	            State::Running,
369	            Event::Ran { .. } | Event::StepFailed { .. } | Event::StepStuck { .. },
370	        ) if job.stage == Stage::Shell => shell_ran(&mut next, event, bounds),
371	        _ => return (job.clone(), Vec::new()),
372	    };
373	    (next, effects)
374	}
375	
376	/// How many times in a row a job may lose its VM before it fails.
377	pub const MAX_REVIVES: u32 = 2;
378	
379	/// Give the job a new VM, which starts its step again once provisioned. A
380	/// VM that keeps dying fails the job rather than looping.
381	fn revive(job: &mut Job) -> Vec<Effect> {
382	    job.failures += 1;
383	    if job.failures > MAX_REVIVES {
384	        return fail(job, "the job's VM was lost again after a revive");
385	    }
386	    job.state = State::Provisioning;
387	    vec![Effect::Provision]
388	}
389	
390	/// A person's retry or extend. `None` means it does not fit, and nothing
391	/// changes.
392	fn by_person(job: &mut Job, event: &Event) -> Option<Vec<Effect>> {
393	    match event {
394	        Event::Retried if job.state == State::Failed => {
395	            job.state = State::Queued;
396	            job.error = None;
397	            job.failures = 0;
398	            Some(Vec::new())
399	        }
400	        Event::Retried if retries(job) => {
401	            job.error = None;
402	            Some(start(job))
403	        }
404	        // The cap counts from `updated_at`, which `step` moved to now.
405	        Event::Extended if extends(job) => Some(Vec::new()),
406	        _ => None,
407	    }
408	}
409	
410	/// Whether the job runs a turn a person may give more time.
411	fn extends(job: &Job) -> bool {
412	    job.state == State::Running && job.stage.kind() == Kind::Turn
413	}
414	
415	/// Whether a person may run the step the job waits on again: it failed, or
416	/// it is stuck.
417	fn retries(job: &Job) -> bool {
418	    job.state == State::Failed
419	        || (job.state == State::NeedsYou && job.error.is_some() && job.question.is_none())
420	}
421	
422	/// Start the current step as [`start`] does, unless its turns have spent
423	/// its budget (D43); then it waits on a person. Only the factory's own
424	/// starts are bounded: a person's retry, note or answer always runs.
425	fn start_within(job: &mut Job, bounds: &Bounds) -> Vec<Effect> {
426	    match over_budget(job, bounds) {
427	        Some(spent) => stuck(job, &spent),
428	        None => start(job),
429	    }
430	}
431	
432	/// Why the current step may not start another turn, when its turns have
433	/// cost its budget or more.
434	fn over_budget(job: &Job, bounds: &Bounds) -> Option<String> {
435	    let step = job.step().filter(|s| s.stage.kind() == Kind::Turn)?;
436	    let budget = step.options.spend_micros?;
437	    let spent = bounds.spent.get(&step.id).copied().unwrap_or_default();
438	    let dollars = |m: u64| format!("${:.4}", m as f64 / 1e6);
439	    (spent >= budget).then(|| {
440	        format!(
441	            "This step's budget of {} is spent: its turns cost {}.",
442	            dollars(budget),
443	            dollars(spent)
444	        )
445	    })
446	}
447	
448	/// Run the current step, once its entry criteria hold: every result
449	/// linked into it exists (D35).
450	fn start(job: &mut Job) -> Vec<Effect> {
451	    job.question = None;
452	    if job.finishing() {
453	        job.state = State::Running;
454	        return vec![Effect::Finish];
455	    }
456	    let needs = job.step().map(|s| s.needs.clone()).unwrap_or_default();
457	    if let Some(missing) = needs.iter().find(|n| !job.results.contains_key(*n)) {
458	        return stuck(
459	            job,
460	            &format!("This step needs the result {missing}, which no step gave."),
461	        );
462	    }
463	    job.state = State::Running;
464	    match job.stage {
465	        Stage::Shell => vec![Effect::RunStep {
466	            stage: Stage::Shell,
467	        }],
468	        stage => vec![Effect::StartTurn {
469	            stage,
470	            brief: brief(job),
471	        }],
472	    }
473	}
474	
475	/// Wait on a person under the step's dial, or go on at once when it is
476	/// dark, or in a trial.
477	fn wait(job: &mut Job, bounds: &Bounds) -> Vec<Effect> {
478	    let dial = job.step().map_or(Dial::LightsOn, |s| s.dial);
479	    if dial == Dial::LightsOn && !bounds.trial {
480	        job.state = State::NeedsYou;
481	        return Vec::new();
482	    }
483	    let decided = Effect::DarkDecided { stage: job.stage };
484	    std::iter::once(decided)
485	        .chain(approved(job, bounds))
486	        .collect()
487	}
488	
489	/// The id of the step the job is at; empty at the finish.
490	fn at_step(job: &Job) -> String {
491	    job.node.clone().unwrap_or_default()
492	}
493	
494	/// A shell step's result, kept as its artifact. Its output is each result
495	/// it declares; a failure goes back to be fixed.
496	fn shell_ran(job: &mut Job, event: &Event, bounds: &Bounds) -> Vec<Effect> {
497	    let step = at_step(job);
498	    let (body, effects) = match event {
499	        Event::Ran { output } => {
500	            job.failed.remove(&step);
501	            for name in job.step().map(|s| s.gives.clone()).unwrap_or_default() {
502	                job.results.insert(name, output.clone());
503	            }
504	            (output.clone(), wait(job, bounds))
505	        }
506	        Event::StepFailed { detail } => (detail.clone(), step_failed(job, detail, bounds)),
507	        Event::StepStuck { detail } => (detail.clone(), stuck(job, detail)),
508	        _ => return Vec::new(),
509	    };
510	    let kept = Effect::RecordArtifact {
511	        stage: Stage::Shell,
512	        step,
513	        body,
514	    };
515	    std::iter::once(kept).chain(effects).collect()
516	}
517	
518	/// A failing shell step sends its output back to the nearest agent's step
519	/// before it, to fix, up to its limit and the workspace's budget. Past
520	/// them, or when the same failure comes back word for word, the job waits
521	/// on a person.
522	fn step_failed(job: &mut Job, detail: &str, bounds: &Bounds) -> Vec<Effect> {
523	    job.failed.extend(job.node.clone());
524	    // A failure link wins over sending the work back to be fixed (D47).
525	    let branch = job.step().and_then(|s| s.on_failure.clone());
526	    let to = match &branch {
527	        Some(target) => job.flow.iter().position(|s| &s.id == target),
528	        None => job.fixer(),
529	    };
530	    let (Some(to), Some(at)) = (to, job.node.clone()) else {
531	        return stuck(job, detail);
532	    };
533	    if budget_spent(job, bounds) {
534	        let budget = bounds.revision_budget.unwrap_or_default();
535	        let spent = format!("The revision budget of {budget} is spent.\n{detail}");
536	        return stuck(job, &spent);
537	    }
538	    let limit = job
539	        .step()
540	        .and_then(|s| s.options.revisions)
541	        .unwrap_or(MAX_REVISIONS);
542	    let tries = job.revisions.entry(at.clone()).or_default();
543	    if *tries >= limit || job.last_refusal.as_deref() == Some(detail) {
544	        return stuck(job, detail);
545	    }
546	    *tries += 1;
547	    job.last_refusal = Some(detail.into());
548	    job.feedback = Some(match branch {
549	        Some(_) => format!(
550	            "The step {at} failed, and its workflow sends the failure here. Its output:\n<output>\n{detail}\n</output>"
551	        ),
552	        None => format!(
553	            "A later step failed. Read its output, fix the cause, and commit.\n<output>\n{detail}\n</output>"
554	        ),
555	    });
556	    job.go_to(to);
557	    start_within(job, bounds)
558	}
559	
560	/// Whether the job's steps have sent its work back as often as its
561	/// workspace allows.
562	fn budget_spent(job: &Job, bounds: &Bounds) -> bool {
563	    let spent: u32 = job.revisions.values().sum();
564	    bounds.revision_budget.is_some_and(|budget| spent >= budget)
565	}
566	
567	/// The job waits on a person at a step that failed: approve goes on
568	/// without it, a note sends it back to be fixed.
569	fn stuck(job: &mut Job, error: &str) -> Vec<Effect> {
570	    job.state = State::NeedsYou;
571	    job.error = Some(error.into());
572	    Vec::new()
573	}
574	
575	/// A person approved, or the dial is dark: the job goes on.
576	fn approved(job: &mut Job, bounds: &Bounds) -> Vec<Effect> {
577	    job.feedback = None;
578	    job.error = None;
579	    advance(job, bounds)
580	}
581	
582	/// The end of a workflow (D41): landed once its branch is merged or left,
583	/// or waiting on a person when that failed; approving finishes again.
584	fn finished(job: &mut Job, event: &Event) -> Vec<Effect> {
585	    match event {
586	        Event::LandFailed { error } => stuck(job, error),
587	        _ => {
588	            job.state = State::Landed;
589	            vec![Effect::Teardown]
590	        }
591	    }
592	}
593	
594	/// Move to the job's next step. Past the last one the job finishes, and a
595	/// trial stops instead, so nothing lands.
596	fn advance(job: &mut Job, bounds: &Bounds) -> Vec<Effect> {
597	    job.last_refusal = None;
598	    // A step only a failure leads to is skipped on the way (D47).
599	    let mut next = job.position().map_or(job.flow.len(), |i| i + 1);
600	    while next < job.flow.len() && job.flow[next].failure_only {
601	        next += 1;
602	    }
603	    if next < job.flow.len() {
604	        job.go_to(next);
605	        return start_within(job, bounds);
606	    }
607	    if bounds.trial {
608	        job.state = State::Stopped;
609	        return vec![Effect::Teardown];
610	    }
611	    job.node = None;
612	    start(job)
613	}
614	
615	fn fail(job: &mut Job, error: &str) -> Vec<Effect> {
616	    job.state = State::Failed;
617	    job.error = Some(error.into());
618	    vec![Effect::Teardown]
619	}
620	
621	/// The results a step must give that `report` lacks (its exit criteria).
622	fn missing_results(job: &Job, report: &str) -> Option<String> {
623	    let given = results(report);
624	    let gives = job.step().map(|s| s.gives.clone()).unwrap_or_default();
625	    let missing: Vec<&String> = gives.iter().filter(|n| !given.contains_key(*n)).collect();
626	    (!missing.is_empty()).then(|| {
627	        let names: Vec<String> = missing.iter().map(|n| format!("RESULT {n}:")).collect();
628	        format!("End the reply with these results: {}", names.join(", "))
629	    })
630	}
631	
632	/// Keep each result the step gives on the job.
633	fn keep_results(job: &mut Job, report: &str) {
634	    let gives = job.step().map(|s| s.gives.clone()).unwrap_or_default();
635	    let mut given = results(report);
636	    for name in gives {
637	        if let Some(body) = given.remove(&name) {
638	            job.results.insert(name, body);
639	        }
640	    }
641	}
642	
643	fn turn_finished(job: &mut Job, outcome: &Outcome, bounds: &Bounds) -> Vec<Effect> {
644	    match outcome {
645	        Outcome::Done { report } => match missing_results(job, report) {
646	            Some(problem) => {
647	                let unusable = Outcome::Unusable {
648	                    report: report.clone(),
649	                    problem,
650	                };
651	                turn_finished(job, &unusable, bounds)
652	            }
653	            None => done(job, report, bounds),
654	        },
655	        Outcome::Unusable { report, problem } => {
656	            job.failures = 0;
657	            let kept = Effect::RecordArtifact {
658	                stage: job.stage,
659	                step: at_step(job),
660	                body: report.clone(),
661	            };
662	            std::iter::once(kept)
663	                .chain(bad_reply(job, problem, bounds))
664	                .collect()
665	        }
666	        Outcome::Asked { question } => {
667	            job.state = State::NeedsYou;
668	            job.question = Some(question.clone());
669	            Vec::new()
670	        }
671	        Outcome::Failed { error } => {
672	            job.failures += 1;
673	            if job.failures >= MAX_TURN_FAILURES {
674	                return fail(job, error);
675	            }
676	            start_within(job, bounds)
677	        }
678	    }
679	}
680	
681	/// A turn that did its step: its report kept, its change captured unless
682	/// it only reads, its results kept, then the dial decides.
683	fn done(job: &mut Job, report: &str, bounds: &Bounds) -> Vec<Effect> {
684	    job.failures = 0;
685	    let step = at_step(job);
686	    let mut effects = vec![Effect::RecordArtifact {
687	        stage: job.stage,
688	        step: step.clone(),
689	        body: report.into(),
690	    }];
691	    if !job.step().is_some_and(|s| s.reach.reads_only) {
692	        effects.push(Effect::CaptureDiff {
693	            stage: job.stage,
694	            step,
695	        });
696	    }
697	    keep_results(job, report);
698	    job.feedback = None;
699	    effects.extend(wait(job, bounds));
700	    effects
701	}
702	
703	/// A reply the factory cannot use gets one more try with the reason, then
704	/// the job waits on a person, as in wipp.
705	fn bad_reply(job: &mut Job, problem: &str, bounds: &Bounds) -> Vec<Effect> {
706	    let at = job.node.clone().unwrap_or_default();
707	    let tries = job.revisions.entry(at).or_default();
708	    if *tries >= 1 {
709	        return stuck(job, problem);
710	    }
711	    *tries += 1;
712	    job.feedback = Some(format!("Your last reply could not be used. {problem}"));
713	    start_within(job, bounds)
714	}
715	
716	/// A note on a step's result sends the work back with it to the nearest
717	/// agent's step, to run again from there. An answer goes to the step that
718	/// asked.
719	fn commented(job: &mut Job, text: &str) -> Vec<Effect> {
720	    if let Some(question) = job.question.take() {
721	        job.feedback = Some(format!("You asked: {question}\nThe answer: {text}"));
722	        return start(job);
723	    }
724	    job.error = None;
725	    job.feedback = Some(text.into());
726	    if let Some(fixer) = job.fixer() {
