        .find_map(|l| l.trim().strip_prefix("GRADE:"))
        .and_then(|n| {
            n.trim()
                .split(|c: char| !c.is_ascii_digit())
                .next()?
                .parse::<u8>()
                .ok()
        })
        .filter(|g| *g <= 10)
}

